+    PlasmaComponents3.ToolButton {
+        id: muteButton
+
+        readonly property var mutedUntil: Notifications.Globals.applicationMutedUntil(headingButtons.modelInterface.desktopEntry, headingButtons.modelInterface.notifyRcName)
+
