+        visible: !headingButtons.modelInterface.inGroup
+            && headingButtons.modelInterface.notificationType !== NotificationManager.Notifications.JobType
+            && (headingButtons.modelInterface.desktopEntry !== "" || headingButtons.modelInterface.notifyRcName !== "")
