+    function applicationMutedUntil(desktopEntry: string, notifyRcName: string): var {
+        const until = desktopEntry ? mutedDesktopEntries[desktopEntry] : mutedNotifyRcNames[notifyRcName];
+        return until ?? null;
+    }
+
+    function muteApplication(desktopEntry: string, notifyRcName: string, until: date): void {
+        if (desktopEntry) {
+            mutedDesktopEntries = Object.assign({}, mutedDesktopEntries, {[desktopEntry]: until});
+        } else if (notifyRcName) {
+            mutedNotifyRcNames = Object.assign({}, mutedNotifyRcNames, {[notifyRcName]: until});
+        }
+    }
+
+    function unmuteApplication(desktopEntry: string, notifyRcName: string): void {
+        // Notifications that arrived meanwhile stay in the history but don't pop up anymore
+        for (let i = pendingNotificationsModel.count - 1; i >= 0; --i) {
+            const idx = pendingNotificationsModel.index(i, 0);
+            if (desktopEntry ? pendingNotificationsModel.data(idx, NotificationManager.Notifications.DesktopEntryRole) === desktopEntry
+                             : pendingNotificationsModel.data(idx, NotificationManager.Notifications.NotifyRcNameRole) === notifyRcName) {
+                pendingNotificationsModel.setData(idx, true, NotificationManager.Notifications.ExpiredRole);
+            }
+        }
+
+        if (desktopEntry) {
+            const muted = Object.assign({}, mutedDesktopEntries);
+            delete muted[desktopEntry];
+            mutedDesktopEntries = muted;
+        } else if (notifyRcName) {
+            const muted = Object.assign({}, mutedNotifyRcNames);
+            delete muted[notifyRcName];
+            mutedNotifyRcNames = muted;
+        }
+    }
+
+    function checkApplicationMutes(): void {
+        const now = Date.now();
+        for (const desktopEntry in mutedDesktopEntries) {
+            if (mutedDesktopEntries[desktopEntry].getTime() <= now) {
+                unmuteApplication(desktopEntry, "");
+            }
+        }
+        for (const notifyRcName in mutedNotifyRcNames) {
+            if (mutedNotifyRcNames[notifyRcName].getTime() <= now) {
+                unmuteApplication("", notifyRcName);
+            }
+        }
+    }
+
+    // Menu entries for how long do not disturb mode should last, starting from now
+    function doNotDisturbDurations(now: date, untilManuallyDisabled: bool): var {
+        var model = [];
+
+        // For 1 hour
+        var d = new Date(now);
+        d.setHours(d.getHours() + 1);
+        d.setSeconds(0);
+        model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "For 1 hour")});
+
+        d = new Date(now);
+        d.setHours(d.getHours() + 4);
+        d.setSeconds(0);
+        model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "For 4 hours")});
+
+        // Until this evening
+        if (now.getHours() < dndEveningHour) {
+            d = new Date(now);
+            // TODO make the user's preferred time schedule configurable
+            d.setHours(dndEveningHour);
+            d.setMinutes(0);
+            d.setSeconds(0);
+            model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "Until this evening")});
+        }
+
+        // Until next morning
+        if (now.getHours() > dndMorningHour) {
+            d = new Date(now);
+            d.setDate(d.getDate() + 1);
+            d.setHours(dndMorningHour);
+            d.setMinutes(0);
+            d.setSeconds(0);
+            model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "Until tomorrow morning")});
+        }
+
+        // Until Monday
+        // show Friday and Saturday, Sunday is "0" but for that you can use "until tomorrow morning"
+        if (now.getDay() >= 5) {
+            d = new Date(now);
+            d.setHours(dndMorningHour);
+            // wraps around if necessary
+            d.setDate(d.getDate() + (7 - d.getDay() + 1));
+            d.setMinutes(0);
+            d.setSeconds(0);
+            model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "Until Monday")});
+        }
+
+        if (untilManuallyDisabled) {
+            // Until "turned off"
+            d = new Date(now);
+            // Just set it to one year in the future so we don't need yet another "do not disturb enabled" property
+            d.setFullYear(d.getFullYear() + 1);
+            model.push({date: d, text: i18nd("plasma_applet_org.kde.plasma.notifications", "Until manually disabled")});
+        }
+
+        return model;
+    }
+
     function revokeInhibitions() {
         notificationSettings.notificationsInhibitedUntil = undefined;
         notificationSettings.revokeApplicationInhibitions();
